# area: protocols
# hypothesis: A read-only property does not satisfy a protocol attribute declared as a settable str, while a plain instance attribute does, and a generic property protocol solves T from the matched attribute.
# spec: typing spec - protocol attribute members are treated as settable unless declared as read-only properties.
from typing import Protocol, TypeVar, reveal_type

T = TypeVar('T')


class Named(Protocol[T]):
    @property
    def label(self) -> T: ...


class Settable(Protocol):
    label: str


class Plain:
    def __init__(self) -> None:
        self.label = 'plain'


class ReadOnly:
    @property
    def label(self) -> str:
        return 'ro'


def show_named(x: Named[T]) -> T:
    return x.label


def show_settable(x: Settable) -> str:
    return x.label


reveal_type(show_named(Plain()))
reveal_type(show_named(ReadOnly()))
print(show_named(Plain()), show_named(ReadOnly()))
print(show_settable(Plain()))

try:
    print(show_settable(ReadOnly()))  # expect-error: read-only property is not settable
except TypeError:
    print('rejected at runtime')
